{
  "name": "opencode-context-canary",
  "version": "0.1.0",
  "description": "Warn when an OpenCode model omits its context-health marker.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context-window",
    "ai"
  ],
  "license": "MIT",
  "author": {
    "name": "Kevin Kipp",
    "url": "https://github.com/third774"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/third774/context-canary.git"
  },
  "bugs": {
    "url": "https://github.com/third774/context-canary/issues"
  },
  "homepage": "https://github.com/third774/context-canary#readme",
  "type": "module",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "build": "tsup src/index.ts --format esm --target es2022 --dts",
    "check": "tsc --noEmit",
    "test": "npm run build && node --test test/*.test.mjs",
    "verify": "npm run check && npm test && npm pack --dry-run",
    "prepublishOnly": "npm run verify"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.7"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.7",
    "@types/node": "^22.15.3",
    "tsup": "^8.5.0",
    "typescript": "^5.9.3"
  },
  "publishConfig": {
    "access": "public"
  }
}
